"""German summaries of background rules, separated by edition."""
from html import escape

PHB_2014 = 'https://www.dndbeyond.com/sources/dnd/phb-2014/personality-and-background'
PHB_2024 = 'https://www.dndbeyond.com/sources/dnd/phb-2024/character-origins'

DESCRIPTIONS = {
    'noble': 'Du stammst aus einem adligen Umfeld und kennst gesellschaftliche Rangordnungen, höfische Umgangsformen und die Bedeutung eines Familiennamens. Bildung und Kontakte prägen diesen Hintergrund ebenso wie Erwartungen und Verpflichtungen gegenüber deiner Familie. Der Hintergrund beschreibt deine bisherige Stellung; er legt weder deine Gesinnung noch deine Klasse fest.',
    'acolyte': 'Dein früherer Alltag war mit einer Glaubensgemeinschaft verbunden. Du kennst Zeremonien, religiöse Überlieferungen und die Aufgaben eines Heiligtums. Ein Tempeldiener muss kein Kleriker sein: Der Hintergrund beschreibt den religiösen Lebensweg, während deine Klasse festlegt, welche Klassenfähigkeiten du besitzt.',
    'hermit': 'Ein bedeutender Teil deines Lebens spielte sich außerhalb des gewöhnlichen gesellschaftlichen Alltags ab. Deine Abgeschiedenheit kann religiös, philosophisch oder persönlich geprägt gewesen sein. Heilkunde und Religion spiegeln Beschäftigung mit körperlichen Bedürfnissen und Sinnfragen wider. Wie lange diese Lebensphase dauerte, wird nicht durch einen festen Spielwert vorgeschrieben.',
    'outlander': 'Du bist mit einem Leben in der Wildnis vertraut. Reisen fern befestigter Straßen, Orientierung und das Überleben mit begrenzten Mitteln gehören zu deiner Erfahrung. Dieser Hintergrund bezeichnet Vertrautheit mit der Natur und eine entsprechende Vergangenheit, nicht eine bestimmte Spezies oder zwingend eine bestimmte gesellschaftliche Kultur.',
    'guild-artisan': 'Du hast ein Handwerk gelernt und gehörst einer beruflichen Gemeinschaft an. Neben praktischem Können kennst du Kunden, Arbeitsabläufe und die wirtschaftlichen Interessen deines Berufs. Die Gilde ist ein konkreter Teil deiner Vergangenheit und kann weiterhin Rechte, Pflichten und Beziehungen mit sich bringen.',
    'criminal': 'Deine Vergangenheit ist mit der Unterwelt verbunden. Du kennst das Umgehen von Hindernissen, heimliches Vorgehen und das Leben außerhalb offizieller Regeln. Der Hintergrund schreibt dir keine böse Gesinnung vor. Welche Vergehen zu deiner Vergangenheit gehören und ob du diesen Lebensweg fortsetzt, ist eine Frage deiner Figur.',
    'charlatan': 'Du hast gelernt, mit Täuschung, Ablenkung und falschen Eindrücken durchzukommen. Geschickte Hände und überzeugende Geschichten gehören zu deinem Repertoire. Die regeltechnischen Fertigkeiten helfen bei passenden Proben; sie bedeuten weder automatische Gedankenkontrolle noch einen Erfolg gegen jede aufmerksame Person.',
    'sailor': 'Du kennst das Leben auf Schiffen und in Häfen. Wachdienst, Wetter, Orientierung und die Zusammenarbeit an Bord prägen deine Erfahrung. Die Regeln unterscheiden sich zwischen den Fassungen deutlich: 2014 steht die Schiffspassage im Mittelpunkt, 2024 erhältst du ein Herkunftstalent für körperliche Auseinandersetzungen.',
    'soldier': 'Du hast militärische Ausbildung und Erfahrung im organisierten Dienst. Disziplin, körperlicher Einsatz und das Handeln in einem Verband bilden den gemeinsamen Kern dieses Hintergrunds. Deine frühere Funktion muss nicht mit deiner heutigen Klasse identisch sein; der Hintergrund verleiht nur die unten aufgeführten Regeln.',
    'urchin': 'Deine frühen Lebensumstände waren von knappen Mitteln und dem Alltag auf den Straßen einer Stadt geprägt. Du hast gelernt, dich unauffällig zu bewegen und mit wenig auszukommen. Deine Kenntnisse städtischer Wege sind ein eigener Vorteil dieses Hintergrunds und unterscheiden sich von einer allgemeinen Erhöhung der Kampfbewegung.',
    'entertainer': 'Du bist mit Auftritten vor Publikum vertraut. Musik, Schauspiel, artistische Darbietungen oder andere Formen der Unterhaltung können deinen bisherigen Beruf geprägt haben. Der Hintergrund verleiht die aufgeführten Fertigkeiten und Werkzeugübungen; eine Bardenklasse oder magische Fähigkeiten entstehen dadurch nicht automatisch.',
    'folk-hero': 'Du stammst aus einfachen Verhältnissen und bist durch eine bedeutsame Tat für andere Menschen bekannt geworden. Zwischen dir und der Bevölkerung besteht eine besondere Verbindung. Dein Ruf ist sozialer Rückhalt, aber keine unbegrenzte Verpflichtung aller Dorfbewohner und kein Schutz vor jeder Konsequenz.',
    'sage': 'Lernen und die Beschäftigung mit überliefertem Wissen haben deinen Lebensweg geprägt. Du kennst gelehrte Arbeitsweisen und beschäftigst dich mit Geschichte sowie arkanen Zusammenhängen. Eine gelehrte Vergangenheit allein bestimmt keine Klasse: Auch ein Charakter ohne Magierklasse kann diesen Hintergrund besitzen.',
    'farmer': 'Dein früheres Leben war von Landwirtschaft und dem Umgang mit Tieren oder Pflanzen bestimmt. Körperliche Arbeit, alltägliche Versorgung und natürliche Zusammenhänge bilden den Kern dieser Herkunft. Sie verbindet praktische Naturkenntnisse mit zusätzlicher Widerstandskraft durch das Herkunftstalent.',
    'artisan': 'Du hast in einem handwerklichen Beruf gearbeitet und den Umgang mit einem gewählten Handwerkszeug gelernt. Genaues Hinsehen und das Gespräch mit Auftraggebern spiegeln sich in deinen Fertigkeiten wider. Anders als der Gildenhandwerker von 2014 enthält diese Herkunft keine automatische Gildenmitgliedschaft.',
    'merchant': 'Kauf und Verkauf, Reisen und der Transport von Waren gehörten zu deinem bisherigen Leben. Du bist mit Verhandlungen und dem Umgang mit Tieren vertraut; Navigationswerkzeug ergänzt deine Reiseerfahrung. Die Herkunft verleiht kein unbegrenztes Warenlager und kein automatisches Eigentum an einem Laden oder einer Karawane.',
    'scribe': 'Du hast dich beruflich mit geschriebenen Texten und Dokumenten befasst. Abschriften, sorgfältiges Prüfen und das Festhalten von Informationen haben deine Aufmerksamkeit geschult. Das Kalligrafiewerkzeug steht für diese Ausbildung; aus dem Hintergrund allein folgen keine magischen Schriftrollen oder besonderen Zauberfähigkeiten.',
    'guard': 'Du hast einen Ort oder eine Gemeinschaft bewacht und dabei Aufmerksamkeit sowie körperlichen Einsatz trainiert. Das Herkunftstalent unterstützt frühes und abgestimmtes Handeln im Kampf. Die Herkunft begründet für sich genommen keine aktuelle Amtsgewalt und keine allgemeine Befugnis, andere Personen festzunehmen.',
    'wayfarer': 'Du hast gelernt, dich unter schwierigen Lebensbedingungen am Rand der Gesellschaft zu behaupten. Menschen einzuschätzen und unauffällig zu bleiben war dabei wichtig. Diese Herkunft ist eine eigene 2024-Option und übernimmt nicht automatisch das Stadtwege-Merkmal des Straßenkindes von 2014.',
    'guide': 'Du kennst längere Wege fern von Städten und bist in der Wildnis zurechtgekommen. Heimlichkeit, Überlebenskunst und Kartenarbeit gehören zu deiner Ausbildung. Ein kleiner Zugang zu druidischer Magie ergänzt diese Herkunft. Du musst dafür keine Druidenklasse wählen und erhältst dadurch auch keine Tiergestalt.',
}

FEATS = {
    'skilled': ('Begabt (Skilled)', 'Du erhältst Übung in drei zusätzlichen Fertigkeiten oder Werkzeugen, frei miteinander kombiniert. Diese Auswahl kommt zu den beiden Hintergrundfertigkeiten und der Werkzeugübung hinzu. Das Talent verleiht Übung, nicht Expertise. Es darf mehrfach gewählt werden.'),
    'alert': ('Wachsam (Alert)', 'Beim Initiativewurf addierst du deinen Übungsbonus. Unmittelbar nach dem Auswürfeln kannst du deine Initiative mit einem bereitwilligen Verbündeten im selben Kampf tauschen. Der Tausch ist ausgeschlossen, wenn einer von euch kampfunfähig ist. Dies ist die 2024-Fassung und kein fester Initiativebonus von +5.'),
    'savage': ('Wilder Angreifer (Savage Attacker)', 'Einmal pro Zug kannst du bei einem Treffer mit einer Waffe deren Schadenswürfel zweimal würfeln und eines der beiden Ergebnisse verwenden. Du addierst die beiden Würfe nicht. Der Vorteil betrifft die Schadenswürfel der Waffe und gewährt keinen zusätzlichen Angriff.'),
    'crafter': ('Handwerker (Crafter)', 'Du erhältst Übung mit drei verschiedenen Handwerkszeugen aus der Schnellherstellungstabelle und 20 Prozent Rabatt beim Kauf nichtmagischer Gegenstände. Nach einer langen Rast kannst du einen zulässigen Ausrüstungsgegenstand herstellen, wenn du das zugeordnete Werkzeug besitzt und darin geübt bist. Er zerfällt nach deiner nächsten langen Rast. Zuordnungen: Zimmermannswerkzeug: Leiter/Fackel; Lederwerkzeug: Behälter/Beutel; Steinmetzwerkzeug: Flaschenzug; Töpferwerkzeug: Krug/Lampe; Schmiedewerkzeug: Metallkugeln/Eimer/Krähenfüße/Wurfhaken/Eisentopf; Tüftlerwerkzeug: Glocke/Schaufel/Zunderkästchen; Weberwerkzeug: Korb/Seil/Netz/Zelt; Holzschnitzwerkzeug: Knüppel/großer Knüppel/Kampfstab.'),
    'healer': ('Heiler (Healer)', 'Mit einer Nutzen-Aktion und einer Anwendung deiner Heilerausrüstung versorgst du eine Kreatur innerhalb von 1,5 m (5 ft). Sie kann einen ihrer Trefferpunktewürfel verbrauchen; du würfelst ihn und heilst sie um das Ergebnis plus deinen Übungsbonus. Wenn du bei der Heilung durch dieses Talent oder einen Zauber mit einem Heilungswürfel eine 1 würfelst, darfst du ihn neu würfeln und musst dann das neue Ergebnis verwenden.'),
    'lucky': ('Glückspilz (Lucky)', 'Du besitzt Glückspunkte in Höhe deines Übungsbonus und erhältst alle verbrauchten Punkte nach einer langen Rast zurück. Beim W20-Wurf für eine eigene W20-Prüfung kannst du einen Punkt für Vorteil ausgeben. Wenn eine Kreatur einen Angriff gegen dich mit dem W20 würfelt, kannst du einen Punkt ausgeben, um dem Wurf Nachteil zu geben. Die 2024-Regel verwendet Vorteil und Nachteil, nicht das Würfelverfahren des gleichnamigen älteren Talents.'),
    'musician': ('Musiker (Musician)', 'Du erhältst Übung mit drei Musikinstrumenten deiner Wahl. Beim Abschluss einer kurzen oder langen Rast kannst du auf einem Instrument spielen, in dem du geübt bist. Verbündete, die das Lied hören, erhalten Heldische Inspiration; ihre Anzahl darf höchstens deinem Übungsbonus entsprechen. Dies gewährt Heldische Inspiration nach den 2024-Regeln, keine Bardische Inspiration und keine zusätzlichen Bardenwürfel.'),
    'brawler': ('Wirtshausschläger (Tavern Brawler)', 'Ein schadenverursachender waffenloser Treffer kann 1W4 plus Stärkemodifikator Wuchtschaden verursachen. Eine 1 auf einem Schadenswürfel deines waffenlosen Angriffs darfst du neu würfeln; das neue Ergebnis gilt. Du bist mit improvisierten Waffen geübt. Einmal pro Zug kannst du bei einem waffenlosen Treffer innerhalb deiner Angriffsaktion zusätzlich zum Schaden das Ziel 1,5 m (5 ft) von dir wegstoßen.'),
    'tough': ('Zäh (Tough)', 'Dein Trefferpunktemaximum steigt beim Erwerb des Talents um das Doppelte deiner Charakterstufe. Für jede spätere Charakterstufe kommen weitere 2 Trefferpunkte hinzu. Auf Stufe 1 sind es also +2, auf Stufe 5 insgesamt +10. Das Talent erhöht weder deinen Konstitutionswert noch direkt deine Rettungswürfe.'),
}
for key, cls in [('cleric', 'Kleriker'), ('wizard', 'Magier'), ('druid', 'Druide')]:
    FEATS[key] = ('Eingeweihter der Magie (' + cls + ')', 'Wähle zwei Zaubertricks und einen Zauber des 1. Grades aus der Zauberliste der angegebenen Klasse. Als Zauberattribut wählst du Intelligenz, Weisheit oder Charisma. Den Zauber des 1. Grades hast du stets vorbereitet; einmal pro langer Rast wirkst du ihn ohne Zauberplatz. Vorhandene passende Zauberplätze kannst du ebenfalls verwenden. Bei einem Stufenaufstieg darfst du einen gewählten Zauber durch einen Zauber gleichen Grades derselben Liste ersetzen. Das Talent ist für unterschiedliche Zauberlisten wiederholbar. Die Wahl einer Liste legt nicht deine Charakterklasse fest.')

VARIANTS = {
    'noble': 'Ritter: Statt Privilegierter Stellung kannst du die Gefolgsleute-Variante verwenden. Drei loyale Begleiter übernehmen alltägliche Dienste; bei einem Ritter ist einer davon ein adliger Knappe. Sie sind keine Kampftruppe, folgen dir nicht in offensichtlich gefährliche Orte und können bei Misshandlung oder ständiger Gefährdung gehen.',
    'criminal': 'Spion: Die gleichen Grundwerte können eine Vergangenheit als Geheimagent statt als gewöhnlicher Verbrecher darstellen. Dadurch entsteht kein zusätzliches zweites Hintergrundmerkmal.',
    'entertainer': 'Gladiator: Deine Darbietungen können aus Schaukämpfen bestehen. Auftrittsmöglichkeiten beziehen sich entsprechend auf Arenen und ähnliche Orte. Das Musikinstrument im Ausrüstungspaket kann durch eine preiswerte, ungewöhnliche Waffe wie Dreizack oder Netz ersetzt werden; das gewährt allein keine Waffenübung.',
    'guild-artisan': 'Gildenhändler: Die Mitgliedschaft kann sich auf Handel statt Herstellung beziehen. Anstelle der Handwerkszeugübung sind Navigationswerkzeug oder eine zusätzliche Sprache möglich; statt des Handwerkszeugs als Startgegenstand sind Maultier und Karren vorgesehen.',
    'sailor': 'Pirat: Statt Schiffspassage kannst du das alternative Merkmal Schlechter Ruf wählen. In zivilisierten Siedlungen sehen viele Menschen aus Angst von einer Meldung kleinerer Vergehen ab. Das ist keine generelle Straffreiheit und schützt nicht vor jeder Obrigkeit.',
}

