def entries(edition):
    fields = ('name', 'key', 'skills', 'tools', 'languages', 'equipment', 'feature', 'rule') if edition == '2014' else ('name', 'key', 'abilities', 'feat', 'skills', 'tools', 'equipment')
    rows = OLD_ROWS if edition == '2014' else NEW_ROWS
    return [dict(zip(fields, row.split('|'), strict=True)) for row in rows.splitlines()]


def render_edition(edition):
    if edition not in ('2014', '2024'):
        return ''
    intro = (
        'Ein Hintergrund der Regelfassung 2014 gewährt zwei Fertigkeitsübungen, die aufgeführten Werkzeugübungen beziehungsweise Sprachen, Startausrüstung und ein besonderes Hintergrundmerkmal. Er gibt nach den Grundregeln weder Attributserhöhungen noch automatisch ein Talent. Übung mit einem Werkzeug bedeutet nicht, dass du dieses Werkzeug als Gegenstand besitzt; dafür ist die Ausrüstungsliste maßgeblich.'
        if edition == '2014' else
        'Wähle aus den drei beim Hintergrund genannten Attributen: Erhöhe eines um 2 und ein anderes um 1 oder alle drei um jeweils 1; kein Wert darf dadurch über 20 steigen. Dazu kommen das festgelegte Herkunftstalent, zwei Fertigkeitsübungen und eine Werkzeugübung. Bei der Ausrüstung wählst du das gesamte Paket A oder stattdessen 50 GM (Option B), nicht beides. Die enthaltenen Münzen gehören bereits zum Paket A.'
    )
    body = '<p>' + intro + '</p><p>Tippe einen Hintergrund an, um Beschreibung, Regelvorteile und Ausrüstung zu öffnen.</p>'
    for d in entries(edition):
        key = d['key']
        en = key.replace('-', ' ').title()
        anchor = 'background-' + edition + '-' + key
        body += '<details class="background-detail" id="' + anchor + '"><summary><strong>' + escape(d['name']) + '</strong> <span>(' + escape(en) + ')</span></summary>'
        body += '<div class="background-content"><h3>Beschreibung</h3><p>' + escape(DESCRIPTIONS[key]) + '</p><h3>Regelwerte · ' + edition + '</h3><dl>'
        if edition == '2024':
            body += '<dt>Attribute zur Auswahl</dt><dd>' + escape(d['abilities']) + '</dd>'
            body += '<dt>Herkunftstalent</dt><dd>' + escape(FEATS[d['feat']][0]) + '</dd>'
        body += '<dt>Fertigkeiten mit Übung</dt><dd>' + escape(d['skills']) + '</dd><dt>Werkzeuge / Fahrzeuge mit Übung</dt><dd>' + escape(d['tools']) + '</dd>'
        if edition == '2014':
            body += '<dt>Zusätzliche Sprachen</dt><dd>' + escape(d['languages']) + '</dd>'
        body += '</dl><h3>Startausrüstung' + (' · Option A' if edition == '2024' else '') + '</h3><p>' + escape(d['equipment']) + '.</p>'
        if edition == '2024':
            body += '<p><b>Option B:</b> Statt dieses Pakets erhältst du 50 GM.</p><h3>' + escape(FEATS[d['feat']][0]) + '</h3><p>' + escape(FEATS[d['feat']][1]) + '</p>'
            body += '<p>Ein Hintergrund verleiht nur die aufgeführten Übungen. Weitere Gegenstände im Paket, beispielsweise ein Spielset, geben nicht automatisch Übung damit. Zusätzliche Sprachen gehören nicht pauschal zu dieser Herkunft; beachte dafür die allgemeinen Regeln der Charaktererschaffung.</p>'
        else:
            body += '<h3>Hintergrundmerkmal: ' + escape(d['feature']) + '</h3><p>' + escape(d['rule']) + '</p>'
            if key in VARIANTS:
                body += '<h3>Variante im Spielerhandbuch</h3><p>' + escape(VARIANTS[key]) + '</p>'
        source = PHB_2014 if edition == '2014' else PHB_2024
        body += '<p><small>Quelle: <a href="' + source + '#' + en.replace(' ', '') + '">Spielerhandbuch ' + edition + ' · ' + escape(en) + '</a>. Regelübersicht in eigenen Worten; vollständige Buchinhalte können eine Freischaltung erfordern.</small></p></div></details>'
    if edition == '2014':
        body += '<h3>Doppelte Übungen und Anpassungen</h3><p>Wenn zwei Quellen dieselbe Fertigkeits- oder Werkzeugübung geben, kannst du eine andere Übung derselben Art wählen. Ein angepasster 2014-Hintergrund kann zwei Fertigkeiten sowie insgesamt zwei Werkzeugübungen oder Sprachen enthalten und ein anderes passendes Hintergrundmerkmal verwenden. Ein neues Merkmal wird mit der Spielleitung ausgearbeitet. Bei der optionalen Ausrüstung über Startgeld entfällt das normale Ausrüstungspaket; die 2024-Alternative von pauschal 50 GM gilt hier nicht automatisch.</p>'
    else:
        body += '<h3>Ältere Hintergründe mit den 2024-Regeln verwenden</h3><p>Bei einem Hintergrund aus einem älteren Buch wählst du die Attribute für +2/+1 oder dreimal +1 frei. Besitzt dieser Hintergrund noch kein Talent, erhältst du ein Herkunftstalent deiner Wahl. Nutzt du zugleich eine ältere Spezies mit Attributserhöhungen, entfallen deren Erhöhungen. Diese Umstellung ist eine Regel zur Charaktererschaffung nach 2024 und verändert nicht rückwirkend die getrennte 2014-Übersicht.</p>'
    return body


